package com.interviewcoach.api;
import com.interviewcoach.model.*;import com.interviewcoach.repo.*;import com.interviewcoach.service.AiService;import com.fasterxml.jackson.databind.JsonNode;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.apache.poi.xwpf.usermodel.XWPFDocument;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.nio.file.*;import java.util.*;import java.io.*;
@RestController @RequestMapping("/api/resumes") public class ResumeController {
 private final ResumeRepo resumes;private final UserRepo users;private final AiService ai;private final Path root;
 public ResumeController(ResumeRepo r,UserRepo u,AiService a,@Value("${app.upload-dir}")String dir){resumes=r;users=u;ai=a;root=Path.of(dir).toAbsolutePath().normalize();}
 @GetMapping("/latest") public Map<String,Object> latest(){return resumes.findFirstByUserIdOrderByCreatedAtDesc(ApiSupport.uid()).map(this::view).orElse(Map.of("uploaded",false));}
 private Map<String,Object> view(Resume r){return Map.of("uploaded",true,"id",r.id,"filename",r.filename,"createdAt",r.createdAt.toString(),"analysis",r.analysis==null?"":r.analysis);}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public Map<String,Object> upload(@RequestParam("file")MultipartFile file)throws IOException{String name=Optional.ofNullable(file.getOriginalFilename()).orElse("resume");String lower=name.toLowerCase(Locale.ROOT);if(file.isEmpty()||file.getSize()>5_000_000||!(lower.endsWith(".pdf")||lower.endsWith(".docx")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provide a nonempty PDF or DOCX up to 5 MB");byte[] bytes=file.getBytes();String extracted;try{if(lower.endsWith(".pdf")){if(bytes.length<5||!new String(bytes,0,Math.min(5,bytes.length)).startsWith("%PDF-"))throw new IOException("Invalid PDF");try(var pdf=Loader.loadPDF(bytes)){extracted=new PDFTextStripper().getText(pdf);}}else{if(bytes.length<4||bytes[0]!='P'||bytes[1]!='K')throw new IOException("Invalid DOCX");try(var doc=new XWPFDocument(new ByteArrayInputStream(bytes))){extracted=doc.getParagraphs().stream().map(p->p.getText()).reduce("",(x,y)->x+"\n"+y);for(var table:doc.getTables())extracted+="\n"+table.getText();}}}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Document unreadable or damaged");}if(extracted.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No readable resume text found");Files.createDirectories(root);String stored=UUID.randomUUID()+(lower.endsWith(".pdf")?".pdf":".docx");Files.write(root.resolve(stored),bytes,StandardOpenOption.CREATE_NEW);Resume r=new Resume();r.user=users.getReferenceById(ApiSupport.uid());r.filename=Path.of(name).getFileName().toString().replaceAll("[^a-zA-Z0-9._-]","_");r.storedName=stored;r.extractedText=extracted.substring(0,Math.min(30000,extracted.length()));resumes.save(r);return view(r);}
 @PostMapping("/analyze")public Map<String,Object> analyze(@RequestParam(defaultValue="Software Engineer")String role){Resume r=resumes.findFirstByUserIdOrderByCreatedAtDesc(ApiSupport.uid()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Upload a resume first"));JsonNode j=ai.askJson("You are a meticulous resume reviewer. Only extract factual skills/projects from provided resume. Return JSON keys score (integer 0..100),summary (string),skills (array of strings),strengths (array),gaps (array),improvements (array),projects (array),learningTopics (array). Score is only an estimate, not a hiring guarantee.","Target role: "+role+"\nUntrusted resume content:\n"+r.extractedText);int score=j.path("score").asInt(-1);if(score<0||score>100||!j.has("summary"))throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"AI resume analysis did not pass validation");r.analysis=j.toString();resumes.save(r);return view(r);}
}
